// Quiz questions: general knowledge with settled answers (geography, science, space, nature, history, sports, food,
// arts, maths, technology). No film / series / game titles (site text rule), nothing political or religiously
// contested. Most entries are bilingual: `q(tr, en, trOptions, enOptions?)` with the correct option first (the server
// shuffles them every game; when `enOptions` is left out the Turkish options are used as they are, e.g. numbers or
// names). `q(tr, null, …)` / `q(null, en, …)` are questions that only make sense in one language (Turkish regions,
// English spelling). `tf(tr, en, answer)` are true / false statements (two options, never shuffled).
// Ids are positions in `QUIZ_BANK` (this first bank, then `QUIZ_BANK_2`): only ever append, never insert in the middle
// (browsers remember seen ids).

export const QUIZ_CATEGORIES = ['general', 'geography', 'science', 'space', 'nature', 'history', 'sports', 'food', 'arts', 'math', 'tech'] as const;
import { QUIZ_BANK_2 } from './quiz-questions-2.ts';

export type QuizCategory = (typeof QUIZ_CATEGORIES)[number];

export type QuizOptions = readonly [correct: string, wrong1: string, wrong2: string, wrong3: string];

export interface QuizEntry {
  c: QuizCategory;
  tr?: { q: string; o: QuizOptions | readonly [string, string] };
  en?: { q: string; o: QuizOptions | readonly [string, string] };
  /** True / false statement: options are fixed (true first) and the correct index comes from `answer`. */
  tf?: boolean;
  /** Difficulty: 1 easy, 2 medium, 3 hard (older entries have none: medium). */
  d?: 1 | 2 | 3;
}

type Opts = readonly [string, string, string, string];

const make =
  (c: QuizCategory) =>
  (tr: string | null, en: string | null, trOptions: Opts, enOptions: Opts = trOptions): QuizEntry => ({
    c,
    ...(tr ? { tr: { q: tr, o: trOptions } } : {}),
    ...(en ? { en: { q: en, o: enOptions } } : {}),
  });

const makeTf =
  (c: QuizCategory) =>
  (tr: string | null, en: string | null, answer: boolean): QuizEntry => ({
    c,
    tf: answer,
    ...(tr ? { tr: { q: tr, o: ['Doğru', 'Yanlış'] as const } } : {}),
    ...(en ? { en: { q: en, o: ['True', 'False'] as const } } : {}),
  });

const general = make('general');
const geography = make('geography');
const science = make('science');
const space = make('space');
const nature = make('nature');
const history = make('history');
const sports = make('sports');
const food = make('food');
const arts = make('arts');
const math = make('math');
const tech = make('tech');
const tf = {
  general: makeTf('general'),
  geography: makeTf('geography'),
  science: makeTf('science'),
  space: makeTf('space'),
  nature: makeTf('nature'),
  history: makeTf('history'),
  sports: makeTf('sports'),
  food: makeTf('food'),
  arts: makeTf('arts'),
  math: makeTf('math'),
  tech: makeTf('tech'),
};

